import matplotlib.pyplot as plt, matplotlib.image as mpimg
for p in ["paper/figs/fig_vgp_diagnosis.png","paper/figs/fig_barcode_comparison.png"]:
    try:
        img=mpimg.imread(p); fig,ax=plt.subplots(figsize=(12,7 if "barcode" in p else 5))
        ax.imshow(img); ax.axis("off"); plt.show()
    except FileNotFoundError:
        print("missing:",p,"(run build_laventa_figs.py first)")
